package app.murmur.core.catalog

import app.murmur.core.model.ArtifactId
import app.murmur.core.model.ComputeUnit
import app.murmur.core.model.ModelId
import app.murmur.core.model.ModelKind
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Model catalog, schema 1 (D3, ARCHITECTURE.md section 8). One JSON document describes every ASR, LLM,
 * OCR and VAD model. The UI renders only these fields; nothing in the UI is model-specific.
 *
 * Bundled copy: src/main/resources/catalog/catalog.json (generated by tools/build_catalog.py from the
 * verified research catalogs). A refreshed copy (later) has the same schema and a higher [catalogVersion].
 */
@Serializable
data class Catalog(
    val schema: Int,
    /** Monotonic "YYYY-MM-DD.N". A refreshed catalog replaces the bundled one only if newer. */
    val catalogVersion: String,
    val generated: String,
    val defaults: CatalogDefaults,
    val packs: List<Pack> = emptyList(),
    val models: List<ModelEntry>,
) {
    fun model(id: ModelId): ModelEntry? = models.firstOrNull { it.id == id }
    fun artifact(id: ArtifactId): Pair<ModelEntry, Artifact>? =
        models.firstNotNullOfOrNull { m -> m.artifacts.firstOrNull { it.id == id }?.let { m to it } }

    companion object {
        const val SCHEMA = 1
    }
}

@Serializable
data class CatalogDefaults(
    /** Language profile ("ru+en", "en", "ru", "he") -> default ASR model. */
    val asr: Map<String, ModelId>,
    /** Default cleanup model; null = None. */
    val llm: ModelId? = null,
    val vad: ModelId,
    val ocrDet: ModelId,
    val ocrRec: ModelId,
)

/** Onboarding "Download the models" radio rows (DESIGN.md 6.1 step 5). */
@Serializable
data class Pack(
    val id: String,
    val title: String,
    val description: String? = null,
    val items: List<ModelId>,
    val recommended: Boolean = false,
)

@Serializable
data class ModelEntry(
    val id: ModelId,
    val kind: ModelKind,
    val displayName: String,
    val publisher: String,
    val family: String,
    /** HF repo of the original model card ("Source" row in the hub). */
    val baseRepo: String? = null,
    val description: String? = null,
    val params: Long? = null,
    val paramsLabel: String? = null,
    val languages: Languages = Languages(),
    val license: License,
    val tier: Tier,
    val status: Status = Status.AVAILABLE,
    val asr: AsrTraits? = null,
    val llm: LlmTraits? = null,
    val ocr: OcrTraits? = null,
    val artifacts: List<Artifact>,
    /** D2: e.g. "npu-port" when the owner asked for the model but no NPU artifact exists today. */
    val followUps: List<FollowUp> = emptyList(),
    val notes: String? = null,
    /** Where the facts were verified (doc path). */
    val evidence: String? = null,
    val origin: Origin = Origin.BUNDLED,
) {
    /** DESIGN.md 6.4: a model whose card does not list Russian gets the "No Russian" badge. */
    val noRussian: Boolean get() = (kind == ModelKind.ASR || kind == ModelKind.LLM) && "ru" !in languages.codes

    /** May be the speech model of record (ADR-047: preview-only streaming models may not). */
    val selectableAsAsr: Boolean get() = kind == ModelKind.ASR && asr?.previewOnly != true && status == Status.AVAILABLE
}

@Serializable
data class Languages(
    val codes: List<String> = emptyList(),
    /** Total language count from the card (may exceed codes.size, e.g. "201 languages"). */
    val count: Int = codes.size,
    val mode: LanguageMode = LanguageMode.AUTO,
    val note: String? = null,
)

@Serializable
enum class LanguageMode {
    /** Detects the language itself, takes no hint (Parakeet). */
    @SerialName("auto") AUTO,
    /** Accepts a language hint, can also auto-detect (Whisper, Nemotron, Qwen3-ASR). */
    @SerialName("hint") HINT,
    /** One language only (GigaAM, T-one). */
    @SerialName("fixed") FIXED,
}

@Serializable
data class License(val id: String, val url: String? = null, val note: String? = null)

@Serializable
enum class Tier {
    @SerialName("recommended") RECOMMENDED,
    @SerialName("optional") OPTIONAL,
    @SerialName("fallback") FALLBACK,
    @SerialName("experimental") EXPERIMENTAL,
    @SerialName("planned") PLANNED,
}

@Serializable
enum class Status {
    @SerialName("available") AVAILABLE,
    /** Listed so the owner sees it; no artifact yet ("In training" badge for fine-tunes). */
    @SerialName("planned") PLANNED,
    @SerialName("in_training") IN_TRAINING,
}

@Serializable
enum class Origin {
    @SerialName("bundled") BUNDLED,
    @SerialName("refreshed") REFRESHED,
    /** Added by the user from a Hugging Face repo (D3 "the user can configure any model"). */
    @SerialName("custom") CUSTOM,
}

@Serializable
data class AsrTraits(
    /** Native streaming (Nemotron, T-one). Batch models are fed VAD segments (D4). */
    val streaming: Boolean,
    val punctuation: Boolean,
    val casing: Boolean,
    val sampleRate: Int = 16_000,
    /**
     * Streaming models kept for a future live preview (Nemotron, A5). v1 has no live preview (ADR-047): the hub
     * lists them as "Preview only, not selectable yet", and the resolver and the validator reject them as the
     * speech model.
     */
    val previewOnly: Boolean = false,
)

@Serializable
data class LlmTraits(
    /** prompts/render.py TEMPLATES key: "qwen3.5" | "qwen3" | "lfm3" | "lfm2.5". */
    val template: String,
    /** prompts/profiles/<name>.json; fine-tunes use a bare system prompt name ("finetuned.v1"). */
    val promptProfile: String,
    /**
     * Context window the :llm process allocates (LoadSpec option n_ctx). Rule (ADR-045): nCtx >=
     * [prefixTokens] + [CONTEXT_RESERVE_TOKENS], rounded up to 1,024, so that a 5-minute dictation (the DESIGN
     * maximum) fits with its screen context and output. Stock default.v1: 7,168 (ADR-085); default.v4: 9,216;
     * finetuned.v1: 6,144.
     */
    val nCtx: Int,
    /**
     * Tokens of render.cache_prefix(promptProfile, template) with this model's tokenizer (VERIFIED with
     * llama-tokenize at catalog generation; the WP-10 tokenizer test pins it). null for custom models: measured at
     * Preparing from PrefixInfo.tokens.
     */
    val prefixTokens: Int? = null,
    /** KV cache bytes per token (F16), for the memory estimate; null = 12,288 (hybrid models). */
    val kvBytesPerToken: Int? = null,
    val note: String? = null,
) {
    companion object {
        /**
         * Everything after the cached prefix for a 5-minute dictation at the conservative 0.40 tokens/char
         * (measured 0.31-0.34 on the ctx v2 goldens, ADR-045): screen + field context 1,850 chars (740 tokens) +
         * transcript 5,000 chars (2,000) + minimum output 1.1 x 2,000 + 16 (2,216), plus 5 % slack.
         */
        const val CONTEXT_RESERVE_TOKENS = 5_200
    }
}

@Serializable
data class OcrTraits(
    @SerialName("stage") val stage: OcrStage,
    /** ml/ocr/config.py PIPELINE_VERSION this model was validated with. */
    val pipelineVersion: String,
)

@Serializable
enum class OcrStage {
    @SerialName("det") DET,
    @SerialName("rec") REC,
}

/** One downloadable build of a model for one runtime (e.g. Parakeet NPU context binaries vs CPU int8 ONNX). */
@Serializable
data class Artifact(
    val id: ArtifactId,
    /** Runtime key, see [RuntimeKeys]. The inference process reports which keys it implements. */
    val runtime: String,
    val format: String,
    val quant: String? = null,
    /** Compute units this artifact can run on, as claimed by the catalog (benchmark verifies). */
    val units: List<ComputeUnit>,
    /** Default unit before any benchmark exists (e.g. LLM spike D4: LFM3 -> NPU, Qwen3.5 -> CPU). */
    val preferredUnit: ComputeUnit? = null,
    /** SoCs the artifact is compiled for (QNN context binaries); empty = any. */
    val socs: List<String> = emptyList(),
    val files: List<FileSpec>,
    /** Role -> path relative to the artifact directory after extraction (encoder, decoder, joiner, tokens, model, dict...). */
    val layout: Map<String, String> = emptyMap(),
    /** Runtime-specific load options forwarded to LoadSpec.options (e.g. "model_type": "zipformer2"). */
    val options: Map<String, String> = emptyMap(),
    /** ASR: fixed per-call window of this build (Parakeet NPU 20 s, Whisper 30 s); null = unbounded. Segmenter hard max = window - 0.5 s. */
    val maxWindowSec: Double? = null,
    /** Expected peak resident memory while loaded, per unit, MB (memory budget, ARCHITECTURE.md section 7). */
    val memoryMb: Map<ComputeUnit, Int> = emptyMap(),
    val notes: String? = null,
) {
    val downloadBytes: Long get() = files.sumOf { it.bytes }
}

@Serializable
data class FileSpec(
    /** Local file name inside the artifact directory (archives are extracted next to it, then deleted). */
    val name: String,
    val url: String,
    val bytes: Long,
    /** Lowercase hex SHA-256 of the downloaded file (for archives: of the archive). Mandatory. */
    val sha256: String,
    val source: FileSource,
    val repo: String,
    /** HF commit sha or GitHub release tag the URL is pinned to. */
    val revision: String,
    val path: String,
    val archive: ArchiveType? = null,
)

@Serializable
enum class FileSource {
    @SerialName("huggingface") HUGGINGFACE,
    /** GitHub release asset (sherpa-onnx SM8750 binaries, Silero VAD). ADR-016. */
    @SerialName("github") GITHUB,
}

@Serializable
enum class ArchiveType {
    @SerialName("tar.bz2") TAR_BZ2,
    @SerialName("zip") ZIP,
}

@Serializable
data class FollowUp(val id: String, val note: String)
